@startuml

class TileO {}

class Connection {}

class Die {}

class ActionCard {
  + type : ActionCardType
}

abstract class Tile {
  + isVisited : boolean
  + isActionTile : boolean
  + turnsAsRegularTile : int
}

class WinTile extends Tile {}

class NormalTile extends Tile {}

class ActionTile extends Tile {}

class PlayingPiece {
  + color : string
}

class Player {
  + id : int
}

enum ActionCardType {
  ROLL_DIE_EXTRA_TURN
  CONNECT_ADJACENT_TILES
  REMOVE_CONNECTION
  MOVE_TO_ARBITRARY_TILE
  LOSE_NEXT_TURN
}

TileO "1" *-- "*" Tile
TileO "1" *-- "1" Die
TileO "1" *-- "32" ActionCard
TileO "1" -- "2..4" Player
Tile "1" -- "0..1" Connection : right
Tile "1" -- "0..1" Connection : left
Tile "1" -- "0..1" Connection : top
Tile "1" -- "0..1" Connection : bottom
Player "1" -- "1" PlayingPiece
PlayingPiece "*" -- "1" Tile

@enduml

